// Remove Flagged Text
// Mode: Run Once for All Items
// Input: the answer of the reviewing model: { output: { findings: [{ text, category, reason }] } }
//
// The reviewer points at pieces of text that must not be published. This node removes
// exactly those pieces from the cleaned copy made by Scan And Redact, and then CHECKS that
// they are gone. Fail closed:
// - a finding that cannot be found in the data means the reviewer and the data disagree,
//   so the answer is safe: false
// - a text that is still there after the removal means safe: false
// The "reason" written by the reviewer is thrown away on purpose: it may quote the secret.

const MARKER = '[REDACTED]';
const MIN_FINDING_LENGTH = 3;   // shorter pieces would damage the text everywhere
const MAX_FINDINGS = 100;

const scan = $('Scan And Redact').first().json;
const review = $input.first().json.output || {};
const flagged = Array.isArray(review.findings) ? review.findings : [];

function refuse(type) {
  const findings = scan.findings.slice();
  findings.push({ type: type, path: '', count: 1 });
  return [{ json: { safe: false, findings: findings, redacted: null } }];
}

// No list at all is not the same as an empty list: without an answer, nothing was reviewed
if (!Array.isArray(review.findings)) {
  return refuse('reviewMissing');
}

if (flagged.length > MAX_FINDINGS) {
  return refuse('tooManyReviewFindings');
}

// 1. The texts to remove: plain text only, no duplicates, longest first
// (so a long piece is removed before a shorter piece that lives inside it)
const texts = [];
const categories = {};
for (const finding of flagged) {
  const text = finding && typeof finding.text === 'string' ? finding.text : '';
  if (text.length < MIN_FINDING_LENGTH) {
    return refuse('invalidReviewFinding');
  }
  if (!texts.includes(text)) {
    texts.push(text);
    const category = typeof finding.category === 'string' ? finding.category : 'other';
    categories[text] = category.slice(0, 30);
  }
}
texts.sort(function (a, b) { return b.length - a.length; });

// 2. Remove them from every text in the data, and count how often each was found
const foundCounts = {};
for (const text of texts) {
  foundCounts[text] = 0;
}

function removeFromValue(value) {
  if (typeof value === 'string') {
    let result = value;
    for (const text of texts) {
      if (result.includes(text)) {
        foundCounts[text] = foundCounts[text] + result.split(text).length - 1;
        result = result.split(text).join(MARKER);
      }
    }
    return result;
  }
  if (Array.isArray(value)) {
    const list = [];
    for (const inner of value) {
      list.push(removeFromValue(inner));
    }
    return list;
  }
  if (value !== null && typeof value === 'object') {
    const copy = {};
    for (const [key, inner] of Object.entries(value)) {
      copy[key] = removeFromValue(inner);
    }
    return copy;
  }
  return value;
}

const redacted = removeFromValue(scan.redacted);

// 3. Every finding must have been found, and none may be left
// A finding that lives inside a longer finding counts as located: it was removed together with the longer one.
for (const text of texts) {
  if (foundCounts[text] > 0) {
    continue;
  }
  let insideLongerFinding = false;
  for (const other of texts) {
    if (other.length > text.length && foundCounts[other] > 0 && other.includes(text)) {
      insideLongerFinding = true;
    }
  }
  if (!insideLongerFinding) {
    return refuse('reviewFindingNotLocated');
  }
}
const afterwards = JSON.stringify(redacted);
for (const text of texts) {
  if (afterwards.includes(text)) {
    return refuse('removalIncomplete');
  }
}

// 4. The final list of findings: what the scanner found, and what the reviewer found.
// Only the kind of finding is kept, never the text.
const findings = scan.findings.slice();
for (const text of texts) {
  findings.push({ type: 'reviewer:' + categories[text], path: '', count: foundCounts[text] });
}

return [{ json: { safe: true, findings: findings, redacted: redacted } }];

// Build Unsafe Result
const input = $input.first().json;
let findings = [{ type: 'reviewFailed', path: '', count: 1 }];
if (Array.isArray(input.findings)) { findings = input.findings; }
return [{ json: { safe: false, findings: findings, redacted: null } }];

// Scan And Redact
// Mode: Run Once for All Items
// Input: one item { data }, where data is any text or any structure (objects and lists).
// Output: one item { safe, findings, redacted }
//
// This is the first layer of the safety check: fixed patterns for things that must never
// leave the workflow (keys, tokens, passwords, addresses with a login, email addresses).
// Every match is replaced by a marker. Then the cleaned copy is scanned AGAIN. Only a copy
// that is clean the second time is called safe.
//
// Rules of this node:
// - It never changes or reads the original in place: it builds a cleaned copy.
// - A finding says WHAT was found and WHERE, never the secret itself.
// - If anything is wrong or unexpected, the answer is safe: false and redacted: null.
//   Callers must use "redacted", never the original.

const MARKER = '[REDACTED]';
const MAX_STRING_LENGTH = 8000;    // longer texts are cut
const MAX_TOTAL_LENGTH = 200000;   // a bigger input is refused
const MAX_DEPTH = 20;

// Each pattern has a name and a way to find matches.
// "mustMix" means: only count the match if it contains both letters and digits.
const PATTERNS = [
  { name: 'privateKey', regex: /-----BEGIN [A-Z ]*PRIVATE KEY-----[\s\S]*?(-----END [A-Z ]*PRIVATE KEY-----|$)/g },
  { name: 'openAiKey', regex: /\bsk-[A-Za-z0-9_-]{20,}/g },
  { name: 'stripeKey', regex: /\b[sr]k_(live|test)_[A-Za-z0-9]{16,}/g },
  { name: 'awsAccessKey', regex: /\b(AKIA|ASIA)[0-9A-Z]{16}\b/g },
  { name: 'githubToken', regex: /\bgh[pousr]_[A-Za-z0-9]{30,}|\bgithub_pat_[A-Za-z0-9_]{40,}/g },
  { name: 'googleKey', regex: /\bAIza[0-9A-Za-z_-]{35}\b/g },
  { name: 'slackToken', regex: /\bxox[abprs]-[A-Za-z0-9-]{10,}/g },
  { name: 'jsonWebToken', regex: /\beyJ[A-Za-z0-9_-]{8,}\.[A-Za-z0-9_-]{8,}\.[A-Za-z0-9_-]{8,}/g },
  { name: 'bearerToken', regex: /\bBearer\s+[A-Za-z0-9._~+\/=-]{16,}/gi },
  { name: 'addressWithLogin', regex: /\b[a-z][a-z0-9+.-]*:\/\/[^\s\/:@]+:[^\s\/@]+@[^\s]+/gi },
  { name: 'secretAssignment', regex: /\b(password|passwd|secret|token|api[_-]?key|apikey|access[_-]?key|private[_-]?key|authorization)\b\s*[:=]\s*["']?(?!\[REDACTED\])[^\s"',;]{6,}/gi },
  { name: 'emailAddress', regex: /\b[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}\b/g },
  { name: 'longRandomString', regex: /\b[A-Za-z0-9+\/_-]{40,}\b/g, mustMix: true }
];

function containsLettersAndDigits(text) {
  return /[A-Za-z]/.test(text) && /\d/.test(text);
}

// Replaces every match in one text. Counts what it found, by pattern name.
function redactText(text, counts) {
  let result = text;
  for (const pattern of PATTERNS) {
    result = result.replace(pattern.regex, function (match) {
      if (pattern.mustMix === true && !containsLettersAndDigits(match)) {
        return match;
      }
      counts[pattern.name] = (counts[pattern.name] || 0) + 1;
      return MARKER;
    });
  }
  return result;
}

// Walks through any structure and builds a cleaned copy.
// Every finding is added to the list with the path where it was found.
function cleanValue(value, path, depth, findings) {
  if (depth > MAX_DEPTH) {
    throw new Error('The data is nested too deeply');
  }

  if (typeof value === 'string') {
    let text = value;
    if (text.length > MAX_STRING_LENGTH) {
      text = text.slice(0, MAX_STRING_LENGTH);
    }
    const counts = {};
    const cleaned = redactText(text, counts);
    for (const [name, count] of Object.entries(counts)) {
      findings.push({ type: name, path: path, count: count });
    }
    return cleaned;
  }

  if (Array.isArray(value)) {
    const list = [];
    for (let i = 0; i < value.length; i++) {
      list.push(cleanValue(value[i], path + '[' + i + ']', depth + 1, findings));
    }
    return list;
  }

  if (value !== null && typeof value === 'object') {
    const copy = {};
    for (const [key, inner] of Object.entries(value)) {
      const innerPath = path === '' ? key : path + '.' + key;
      copy[key] = cleanValue(inner, innerPath, depth + 1, findings);
    }
    return copy;
  }

  return value; // numbers, true, false, null
}

function refuse(reason) {
  return [{ json: { safe: false, findings: [{ type: reason, path: '', count: 1 }], redacted: null } }];
}

// 1. Read the input
const input = $input.first().json.data;
if (input === undefined || input === null) {
  return refuse('noData');
}

let data = input;
if (typeof input === 'string') {
  try {
    data = JSON.parse(input);
  } catch (error) {
    data = input; // plain text is fine
  }
}

if (JSON.stringify(data).length > MAX_TOTAL_LENGTH) {
  return refuse('inputTooLarge');
}

// 2. First pass: clean, and note what was found
const findings = [];
let redacted = null;
try {
  redacted = cleanValue(data, '', 0, findings);
} catch (error) {
  return refuse('inputNotReadable');
}

// 3. Second pass over the cleaned copy. Anything found now means the cleaning was not enough.
const secondFindings = [];
cleanValue(redacted, '', 0, secondFindings);
const cleanTwice = secondFindings.length === 0;

if (!cleanTwice) {
  return refuse('redactionIncomplete');
}

return [{ json: { safe: true, findings: findings, redacted: redacted } }];
